    const float* matrix_rows = &matrix.basis_right.x;
    float trace = matrix_rows[5] + matrix_rows[0] + matrix_rows[10] + 1.0f;
    if (trace > 0.000001f) {
        float scale = 0.5f / Sqrt(trace);
        w = 0.25f / scale;
        x = (matrix_rows[6] - matrix_rows[9]) * scale;
        y = (matrix_rows[8] - matrix_rows[2]) * scale;
        z = (matrix_rows[1] - matrix_rows[4]) * scale;
        return;
    }

    float radicand;

    if (matrix_rows[0] < matrix_rows[5]) {
        goto right_less_than_up;
    }
    if (matrix_rows[0] > matrix_rows[10]) {
        goto x_dominant;
    }
    if (matrix_rows[5] > matrix_rows[10]) {
        goto y_dominant;
    }

z_dominant:
    {
        radicand = matrix_rows[10] + 1.0f - matrix_rows[0] - matrix_rows[5];
        if (radicand < 0.0f) {
            debug_report_stub("ERROR:sqt %f\n", radicand);
            radicand = 0.0f;
        }

        radicand = Sqrt(radicand);
        radicand = radicand + radicand;
        x = (matrix_rows[8] + matrix_rows[2]) / radicand;
        y = (matrix_rows[9] + matrix_rows[6]) / radicand;
        z = radicand * 0.25f;
        w = (matrix_rows[4] + matrix_rows[1]) / radicand;
        return;
    }

right_less_than_up:
    if (matrix_rows[5] >= matrix_rows[10]) {
        goto y_dominant;
    }
    if (matrix_rows[0] <= matrix_rows[10]) {
        goto z_dominant;
    }

x_dominant:
    {
        radicand = matrix_rows[0] + 1.0f - matrix_rows[5] - matrix_rows[10];
        if (radicand < 0.0f) {
            debug_report_stub("ERROR:sqrt %f\n", radicand);
            radicand = 0.0f;
        }

        radicand = Sqrt(radicand);
        radicand = radicand + radicand;
        x = radicand * 0.25f;
        y = (matrix_rows[4] + matrix_rows[1]) / radicand;
        z = (matrix_rows[8] + matrix_rows[2]) / radicand;
        w = (matrix_rows[9] + matrix_rows[6]) / radicand;
        return;
    }

y_dominant:
    {
        radicand = matrix_rows[5] + 1.0f - matrix_rows[0] - matrix_rows[10];
        if (radicand < 0.0f) {
            debug_report_stub("ERROR:sqt %f\n", radicand);
            radicand = 0.0f;
        }

        radicand = Sqrt(radicand);
        radicand = radicand + radicand;
        x = (matrix_rows[4] + matrix_rows[1]) / radicand;
        y = radicand * 0.25f;
        z = (matrix_rows[9] + matrix_rows[6]) / radicand;
        w = (matrix_rows[8] + matrix_rows[2]) / radicand;
        return;
    }
}
